// ===================== ECONOMY, POLITICS, SURVIVAL =====================
let SRC = null;
const withSrc = (label, fn) => { const o = SRC; SRC = label; try { return fn(); } finally { SRC = o; } };
function addMod(c, k, v, months) { c.mods.push({ k, v, t: months, src: SRC }); }
