  const dp = debtPct(c);
  const rate = clamp(c.rateBase + 0.35 * (c.infl - c.baseInfl) + Math.max(0, dp - Math.max(c.dpRef, 60)) * (c.iso === S.player ? 0.02 : 0.04) + creditPrem(c) + (c.flags.creditHit || 0), 0.3, 25);
